mapper.select:
SELECT
    COUNT(*) AS transaction_count,
    COALESCE(ROUND(AVG(amount), 0), 0) AS average_amount
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND type = 'EXPENSE'
  AND amount > 0
  AND category <> 'CARD_WITHDRAWAL'
  AND (
      category = #{category}
      OR (#{category} = 'ETC' AND category = 'OTHER')
  )
  AND transaction_date BETWEEN #{startDate} AND #{endDate}

mapper.update:
UPDATE FEED
SET spending_type = #{spendingType},
    category = #{category},
    custom_category = NULL,
    caption = #{caption},
    saving_amount = #{savingAmount}
WHERE id = #{feedId}
  AND user_id = #{userId}
  AND challenge_id = #{challengeId}
  AND status = 'ACTIVE'

UPDATE FEED_ANALYSIS
SET recommended_spending_type = #{spendingType},
    recommended_category = #{category},
    estimated_saving_amount = #{savingAmount}
WHERE feed_id = #{feedId}

UPDATE FEED_ANALYSIS fa
JOIN FEED f ON f.id = fa.feed_id
SET fa.analysis_accuracy = #{rating},
    fa.analysis_feedback_note = #{note},
    fa.analysis_feedback_at = CURRENT_TIMESTAMP
WHERE fa.feed_id = #{feedId}
  AND f.user_id = #{userId}
  AND f.challenge_id = #{challengeId}
  AND f.status = 'ACTIVE'

UPDATE FEED
SET status = 'DELETED', file_deleted_at = CURRENT_TIMESTAMP
WHERE id = #{feedId}
  AND user_id = #{userId}
  AND challenge_id = #{challengeId}
  AND status = 'ACTIVE'
